INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'october-fuel-price-rise-forecast-inland-petrol-above-r29-2026-09-15',
  'Motorists warned of a steep petrol and diesel increase in October',
  'Business', '2026-09-15', 'Polokwane Review-Observer', 'https://www.citizen.co.za/review-online/news-headlines/local-news/2026/09/15/october-petrol-price-hikes-could-push-petrol-above-r29/',
  'Central Energy Fund figures for the first half of September point to fuel increases of more than R2 a litre in October, which could take inland 95 petrol past R29.',
  'Fuel users in Polokwane and the rest of the inland region should brace for a large increase at the pumps next month. The Polokwane Review-Observer reports that the Central Energy Fund''s figures for the first half of the month point to sharp increases in October.

According to that data, 93 petrol is currently heading for a rise of R2.29 a litre and 95 petrol for R2.41 a litre. Wholesale diesel with 0.05% sulphur is projected to go up by R2.04 a litre, while the 0.005% sulphur grade could rise by R2.41 a litre. Illuminating paraffin is projected to rise by R2.56 a litre. The newspaper says the inland price of 95 petrol could climb above R29 a litre.

The paper puts the extra cost of filling a 45 litre petrol tank at about R108 compared with September, and the extra cost of a 100 litre diesel fill-up at roughly R200. eNCA reported on 14 September that the expected rise is driven by high oil prices, with Brent crude trading above 108 dollars a barrel, and by a weak rand at around R16.25 to the dollar.

These figures are projections based on data collected so far, not the final adjustment. The official October prices will only be confirmed by government once the full month of data is in, and they could still move up or down before then. Households and businesses that budget for transport may want to plan for a higher fuel bill in October.',
  NULL, NULL, NULL,
  '["https://www.citizen.co.za/review-online/news-headlines/local-news/2026/09/15/october-petrol-price-hikes-could-push-petrol-above-r29/", "https://www.enca.com/business-top-stories/fuel-pain-motorists-face-another-steep-price-hike-october"]',
  'agent'
);

INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'limpopo-among-seven-provinces-free-of-eskom-load-reduction-2026-09-19',
  'Limpopo is one of seven provinces now free of Eskom load reduction',
  'Utilities', '2026-09-19', 'Sunday Times', 'https://www.sundaytimes.timeslive.co.za/business/2026-09-19-eskom-removes-12m-from-load-reduction-but-gauteng-is-slow/',
  'Eskom figures show Limpopo has been removed from the load reduction schedule entirely, while Gauteng and KwaZulu-Natal are still working through theirs.',
  'Households and businesses across Limpopo, including the Polokwane area, are no longer on Eskom''s load reduction schedule. The Sunday Times reports that Limpopo is one of seven provinces where load reduction has been eliminated altogether. The others are Mpumalanga, the Eastern Cape, the Western Cape, the Free State, the North West and the Northern Cape.

Eskom said in an update on 21 August that Limpopo and Mpumalanga together had 163 feeders taken off the schedule, against a target of 150, and that the change benefited 670,785 customers in the two provinces. The Sunday Times reports that as of 11 September, Eskom had removed 1,222,430 customers from load reduction nationally, against a target of 1,694,388, and had taken 571 of a planned 971 feeders off the schedule.

Two provinces are still lagging. Gauteng had cleared 244 of its 604 target feeders, and KwaZulu-Natal had cleared 135. According to the Sunday Times, Eskom''s chairperson Mteto Nyati said the work is much more difficult in these two provinces because of more resistance.

For Polokwane residents, the news means that the load reduction schedule no longer applies to them. Eskom says the load reduction still affects a smaller share of its customers nationally, about 6.8% of its customer base.',
  NULL, NULL, NULL,
  '["https://www.sundaytimes.timeslive.co.za/business/2026-09-19-eskom-removes-12m-from-load-reduction-but-gauteng-is-slow/", "https://www.eskom.co.za/eskoms-turnaround-gains-momentum-as-weekly-eaf-reaches-72-56-outage-levels-decline-sharply-and-load-reduction-impact-falls-to-6-8-as-seven-provinces-are-removed-from-the-load-reduction-schedule/"]',
  'agent'
);
